mapper.select:
select ${text} as "text"
from ${table}
where ${code} = #{key}

SELECT COUNT(*)
FROM ${tableName}
WHERE ${fieldName} = #{fieldVal}
  and id <> #{dataId}

SELECT COUNT(*)
FROM ${tableName}
WHERE ${fieldName} = #{fieldVal}

select ${text} as "text", ${code} as "value"
from ${table}
where ${text} like #{keyword}

select ${text} as "title",
${code} as "key",

    (case when ${hasChildField} = '1' then 0 else 1 end) as isLeaf,

${pidField} as parentId,
flag
from ${table}
where


        ${pidField} = #{pid}


        (${pidField} = '' OR ${pidField} IS NULL)



    and flag = #{flag}



        and ${key} = #{value}

select ${query.text} as "text",${query.code} as "value" from ${query.table}
where 1 = 1

    and (${query.text} like '%${query.keyword}%' or ${query.code} like '%${query.keyword}%')


    and ${query.code} = #{query.codeValue}
